// 计算持续时间
const lvl = Math.max(1, move.computedLevel || 1);
const rounds = 1 + (lvl - 1);

// 获取AE模板
const eff = thisItem.effects.getName("混元").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
eff.duration = { rounds: rounds };

await game.xjzl.api.effects.addEffect(actor, eff);

// 1. 混元强化提示
const hasHunyuan = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "hunyuan");
if (hasHunyuan) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card" style="padding-left: 5px;"><p><i class="fas fa-info-circle"></i> <b>混沌未形：</b><br>当前处于[混元]状态，获得 <b>不可被招式选中</b> 效果。<br>(请GM手动处理)</p></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

// 2. 施加延时回血状态
const lvl = Math.max(1, move.computedLevel || 1);
const calcHeal = 40 + (lvl - 1) * 30;

// 获取AE模板
const eff = thisItem.effects.getName("运气中").toObject();
delete eff._id;
eff.origin = thisItem.uuid;

// 动态修改脚本中的回血数值
const scriptObj = eff.flags["xjzl-system"].scripts.find(s => s.trigger === "turnStart");
if (scriptObj) {
    scriptObj.script = `
        if (actor.system.resources.rage.value === 0) {
            await actor.applyHealing({ amount: ${calcHeal}, type: "hp", showScrolling: true });
            ui.notifications.info("混沌未形：气息归田，回复气血。");
        } else {
            ui.notifications.warn("混沌未形：心有怒气，回血失败。");
        }
        await thisEffect.delete();
    `;
}

await game.xjzl.api.effects.addEffect(actor, eff);

ChatMessage.create({
