    speaker: ChatMessage.getSpeaker({actor: actor})
});

// 检测负面状态
const s = actor.statuses;
const f = actor.xjzlStatuses;
if (f.unstable || s.has("unstable") || s.has("prone") || s.has("root") || f.forceSpeedZero || s.has("blind") || s.has("deaf")) {

    // [修复] 获取源武学 Item (通过 origin 反查)
