            <h3 style="margin:0;">混元回血</h3>
        </div>
        <div class="card-content" style="font-size:0.9em; color:#555;">
            <p><b>触发条件满足</b></p>
            <p>处于负面状态受击。</p>
            <p>请在<b>攻击者回合结束时</b>点击：</p>
        </div>
        <div class="card-buttons">
            <button data-action="applyHeal">
                <i class="fas fa-heart"></i> 回复 20 气血
            </button>
        </div>
    </div>`;

    ChatMessage.create({
        content: content,
        speaker: ChatMessage.getSpeaker({actor: actor}),
        flags: {
            "xjzl-system": {
                actionType: "heal",
                damage: 20,
                itemId: itemId // 使用反查到的正确 ID
            }
        }
    });
    actor.showFloatyText("混元触发", { fill: "#00FFFF" });
}

const lvl = Math.max(1, move.computedLevel || 1);
const rounds = 1 + (lvl - 1);
const effectData = thisItem.effects.getName("破绽").toObject();
delete effectData._id;
effectData.origin = thisItem.uuid;
effectData.duration = { rounds: rounds };
await game.xjzl.api.effects.addEffect(args.target, effectData);

const target = game.user.targets.first()?.actor;
const lvl = Math.max(1, move.computedLevel || 1);
const bonus = lvl - 1;
let winText = "压制成功！请手动点击卡片上的【应用伤害】。";
const poJian = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "pojian");
if (poJian) winText += "<br><b>破箭强化：</b>可选 击飞5米 / 击退5米 / 击倒并禁足。";

if (target) {
    await Macros.requestContest({
        attacker: actor,
        defender: target,
        type: "wuxue",
        defType: "wuxue",
        label: "破剑诀 - 招式对抗",
        attBonus: bonus,
        outcome: {
            win: { text: winText },
            lose: { text: "对抗失败，压制无效。请勿应用伤害。" }
        }
